// Generated by Cypress Author on 2026-11-24.
// Group the empty-password authentication scenario.
describe('Swag Labs authentication', () => {
  // Define the single login scenario with a blank password.
  it('empty password → stays on the login page and shows an error', () => {
    // Open the Swag Labs login page.
    cy.visit('/');

    // Enter the standard user's username.
    cy.get('[data-test="username"]').type('standard_user');
    // Leave the password field blank and submit the login form.
    cy.get('[data-test="login-button"]').click();

    // Confirm the browser remains on the login page.
    cy.location('pathname').should('eq', '/');
    // Confirm the error is visible and contains the expected password-required message.
    cy.get('[data-test="error"]').should('be.visible').and('contain', 'Epic sadface: Password is required');
  });
});
